import fs from 'node:fs';import {A,assets,c,root,createCanvas} from './tests/load-assets.mjs';import {createJangmokEnvironment} from './environment.mjs';import {NativeHomeSession} from './session.mjs';import {renderNativeHome} from './render.mjs';
const masks=Object.fromEntries(Object.entries(c.masks).map(([k,s])=>[k,new Uint8Array(fs.readFileSync(new URL(s.path,root)))])),environment=createJangmokEnvironment(A),canvas=createCanvas(960,540),rows=[];let s;
function render(name){const status=s.snapshot(),r=renderNativeHome(canvas.getContext('2d'),{contract:c,assets,environment,status});fs.writeFileSync(new URL(name+'.png',root),canvas.toBuffer('image/png'));rows.push({file:name+'.png',kind:'OFFLINE_SAME_RUNTIME_RENDER_NOT_BROWSER',status,...r});globalThis.gc?.()}
function walk(points){for(const p of points.slice(1)){const[x,y]=s.foot;if(!s.move(p[0]<x?'left':p[0]>x?'right':p[1]<y?'up':'down').ok)throw Error('UNSUPPORTED_PROOF_ROUTE')}}
s=new NativeHomeSession({contract:c,homeId:'upper',masks});s.setDoorState('OPEN');walk(s.h.exteriorDoor.approachRoute);render('01_UPPER_DOOR_DAY');environment.setTime(1320);render('02_UPPER_DOOR_NIGHT');await s.action();s.releaseAction();environment.tick(600);render('03_UPPER_1F');walk(c.floors.upper_1F.routes.entryArrival_stair);await s.action();s.releaseAction();environment.tick(600);render('04_UPPER_2F');walk(c.floors.upper_2F.routes.stairArrival_stair);await s.action();s.releaseAction();walk(c.floors.upper_1F.routes.stairArrival_entry);s.face('down');render('05_UPPER_EXIT_READ');await s.action();s.releaseAction();render('06_UPPER_RETURN_NIGHT');s.dispose();s=new NativeHomeSession({contract:c,homeId:'family',masks});s.setDoorState('OPEN');walk(s.h.exteriorDoor.approachRoute);render('07_FAMILY_DOOR_NIGHT');environment.setTime(720);render('08_FAMILY_DOOR_DAY');await s.action();s.releaseAction();environment.tick(600);render('09_FAMILY_1F');walk(c.floors.family_1F.routes.entryArrival_entry);s.face('down');render('10_FAMILY_EXIT_READ');await s.action();s.releaseAction();environment.setTime(1320);s.face('right');render('11_FAMILY_RETURN_RIGHT_NIGHT');fs.writeFileSync(new URL('PROOF_METADATA.json',root),JSON.stringify({status:'OFFLINE_NATIVE11FRAMES_SAME_RENDERER',actualBrowser:false,rows},null,2)+'\n');
